{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "CLR457, the closest analogue sharing the morpholino-triazine and CF3-aminoheteroaryl core, had a brain/plasma AUC ratio of only 0.07, indicating minimal CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A CF3-pyridine/morpholine-containing analogue (compound 22) showed poor brain penetration with a Bu/Pu ratio of 0.08.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Compound 8, another CF3-pyridine/morpholine analogue, had an unacceptable Bu/Pu ratio of 0.11 in rat brain PK.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A fused morpholine/aminopyridine analogue (12b) produced minimal total brain exposure (AUC0-8 = 104 ng·h/g) after oral dosing, consistent with poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A morpholinopyrimidine radioligand showed good brain uptake (SUV 2.8) in rats, demonstrating that direct morpholine-heteroaryl motifs are not universally non-penetrant; however, it lacks the triazine and CF3-aminopyridine features of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "GNE-7915, a CF3-pyridine/morpholine amide analogue, achieved a brain unbound/plasma unbound ratio of 0.69 in non-human primates, showing that this general feature set can be brain penetrant when the scaffold is optimized.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query's bis-morpholino triazine plus CF3-aminopyridine scaffold is most closely mirrored by CLR457, which had minimal brain penetration (brain/plasma AUC 0.07), and several other morpholine/CF3-pyridine analogues also showed low Bu/Pu ratios or minimal brain exposure. Although some morpholine-containing compounds are brain penetrant, the direct triazine-based poor-penetration evidence and consistent poor CNS exposure among close analogues outweigh the counterexamples, predicting inadequate CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or unbound brain concentration measurement exists for the exact query molecule; the closest analogue has only moderate Morgan similarity (0.39).",
    "No P-gp/BCRP efflux or transporter data are available for the query; efflux liability is inferred from close analogues.",
    "Most evidence is from rodent/NHP studies; human CNS exposure for this chemotype is not directly established."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

